/* Hide all symbols except a few required ones.
 *
 * Otherwise LLVM symbols conflict with Mesa llvm pipe, boost symbols conflict
 * with Luxrender, etc. */
{
global:
  /* _fini and _init are deliberately absent: bionic's crt objects do not define
   * them, and the link runs with --no-undefined-version, so naming them here fails
   * with "version script assignment of 'global' to symbol '_init' failed". */
  /* The NativeActivity glue's entry point. Android's NativeActivity.onCreate does a
   * dlsym() for exactly this name on whatever library System.loadLibrary() returned,
   * so if 'local: *' below hides it the APK installs and then dies in onCreate with
   *   java.lang.UnsatisfiedLinkError: ... undefined symbol: ANativeActivity_onCreate
   * The glue is linked (android_native_app_glue.c, from the NDK) and referenced with
   * -Wl,-u, but both only put the symbol in the link; the version script is what
   * decides whether it reaches .dynsym. android_main goes with it. */
  ANativeActivity_onCreate;
  android_main;
  /* The JNI entry points of BlenderActivity, resolved by name from the JVM: the VM
   * looks each one up with dlsym() on the library System.loadLibrary() returned, so
   * 'local: *' hides them just as surely as it hid ANativeActivity_onCreate above.
   * Nothing reports a missing one at build time or at load -- the library opens
   * fine and the failure only shows up when the method is first called:
   *   java.lang.UnsatisfiedLinkError: No implementation found for void
   *     com.kronos3d.app.BlenderActivity.nativeSendKeyCombo(int, int, int)
   *   (tried Java_com_kronos3d_app_BlenderActivity_nativeSendKeyCombo and
   *    Java_com_kronos3d_app_BlenderActivity_nativeSendKeyCombo__III)
   *   - is the library loaded, e.g. System.loadLibrary?
   * which killed the app the moment the Kronos shortcuts panel sent its first key.
   * Five methods ride on this: nativeOnCommitText, nativeOnKey,
   * nativeOpenMainFile, nativeSendKeyCombo and nativeSetModifierLatched -- the
   * on-screen keyboard, opening a .blend from a file manager, and the shortcuts
   * panel. Java_* matches only the mangled-free JNI names, so it exposes these
   * and nothing else. */
  Java_*;
  /* Needed for Python modules to work. */
  Py*;
  _Py*;
  /* Needed for sanitizers. Based on:
   * llvm/compiler-rt/lib/sanitizer_common/scripts/gen_dynamic_list.py. */
  __asan*;
  __lsan*;
  __tsan*;
  __ubsan*;
  __sanitizer*;
  /* Memory allocation (new, delete, malloc). */
  __Znw*;
  __Zna*;
  __Zdl*;
  __Zda*;
  aligned_alloc*;
  calloc*;
  free*;
  mallinfo*;
  malloc*;
  mallopt*;
  memalign*;
  memcpy*;
  posix_memalign*;
  pthread_*;
  pvalloc*;
  realloc*;
  realpath*;
  sched_*;
  valloc*;
  /* Needed on FreeBSD. Uses wildcard to avoid linker error when symbols are not found. */
  __progname*;
  environ*;
local:
  *;
};
